const stores=[{id:'all',name:'全部门店',sales:186420,target:210000,cost:.348,labor:.228,profit:.123,orders:3540},{id:'s1',name:'中心广场店',sales:42680,target:45000,cost:.326,labor:.21,profit:.17,orders:820},{id:'s2',name:'万象城店',sales:38450,target:42000,cost:.332,labor:.219,profit:.149,orders:702},{id:'s3',name:'滨江店',sales:28960,target:38000,cost:.392,labor:.268,profit:.053,orders:594},{id:'s4',name:'大学城店',sales:35120,target:39000,cost:.341,labor:.218,profit:.131,orders:756},{id:'s5',name:'高新园店',sales:41210,target:46000,cost:.358,labor:.236,profit:.103,orders:668}];
for(const key of ['cost','labor','profit']) stores[0][key]=stores.slice(1).reduce((n,s)=>n+s.sales*s[key],0)/stores[0].sales;
const state={store:'all',day:'yesterday',period:'7',rank:'sales'};const titles={home:'老板经营看板',revenue:'营收达成率',profit:'经营利润',cost:'食材成本率',labor:'人工成本率',cash:'资金概览',stores:'门店经营排名',store:'门店经营详情',orders:'订单与客单价'};let savedScroll={};
const money=n=>Math.round(n).toLocaleString('zh-CN');const pct=n=>(n*100).toFixed(1)+'%';const value=n=>n>=10000?(n/10000).toFixed(2):money(n);const unit=n=>n>=10000?'万':'元';const factor=()=>state.day==='week'?6.7:state.day==='month'?16.4:1;const current=()=>{const s=stores.find(s=>s.id===state.store)||stores[0],f=factor();return {...s,sales:Math.round(s.sales*f),target:Math.round(s.target*f),orders:Math.round(s.orders*f)}};
const currentRoute=()=>location.hash.slice(1)||'home';function persist(){history.replaceState({demo:true,filters:{...state},scroll:window.scrollY,depth:history.state?.depth||0},'')}function go(route,store){persist();if(store)state.store=store;history.pushState({demo:true,filters:{...state},scroll:0,depth:(history.state?.depth||0)+1},'', '#'+route);render();window.scrollTo(0,0)}function section(t,sub=''){return `<div class="section-title"><span>${t}</span><small>${sub}</small></div>`}function foot(){return '<div class="footer">演示数据 · 非真实经营数据<br>移动端交互原型</div>'}function filter(){return `<div class="filters"><select aria-label="门店范围" id="store-filter">${stores.map(s=>`<option value="${s.id}" ${state.store===s.id?'selected':''}>${s.name}</option>`).join('')}</select><select aria-label="统计日期" id="day-filter">${[['yesterday','昨日 · 09/17'],['week','近 7 天'],['month','本月累计']].map(([id,n])=>`<option value="${id}" ${state.day===id?'selected':''}>${n}</option>`).join('')}</select></div>`}
function hero(detail){const s=current();return `<div class="hero ${detail?'detail-hero':''}"><div class="brand">${detail?titles[detail]:'示范餐饮品牌'}</div><div class="hero-sub">${detail?s.name:'直营门店 '+(state.store==='all'?'5 家':'1 家')+' · 经营数据总览'}</div>${detail?'':`<div class="hero-row"><div><label>营业目标达成率</label><div class="hero-score">${pct(s.sales/s.target)}<small>▾</small></div></div><div style="text-align:right"><label>未达标门店</label><div style="font-size:21px">${state.store==='all'?'5':'1'}<small style="font-size:12px"> 家</small></div></div></div>`}${filter()}</div>`}
function metric(label,note,v,route,bad=true){return `<button class="metric-row" data-go="${route}"><div class="row"><strong>${label} ▸</strong><b>${v}<i class="dot ${bad?'red':'green'}"></i></b></div><div class="minor ${bad?'red':'green'}">${note}</div></button>`}
function kpi(label,v,u,note,route,bad=false){return `<button class="kpi" data-go="${route}"><div class="kpi-label">${label} ▸</div><div class="kpi-value">${v}<small>${u}</small></div><div class="kpi-note ${bad?'red':'green'}">${note}</div></button>`}
function chart(kind='sales'){const s=current();const arr=state.period==='30'?[72,95,98,108,127,104,99,113,96,88,91,96,106,103,79,92,80,106,99,125,106,79,98,106,108,114,112,96,104,89]:[91,99,103,94,107,96,89];const ending=kind==='cost'?s.cost*100:kind==='profit'?s.profit*100:s.sales/s.target*100;const vals=arr.map(v=>ending+(v-arr[arr.length-1])*(kind==='cost'?.09:kind==='profit'?.06:1));const ref=kind==='cost'?35:kind==='profit'?15:100;const max=Math.ceil((Math.max(...vals,ref)+2)/5)*5,min=Math.floor((Math.min(...vals,ref)-2)/5)*5;const refY=145-(ref-min)/(max-min)*113;const pts=vals.map((v,i)=>[32+i*300/(vals.length-1),145-(v-min)/(max-min)*113]);return `<svg class="chart" viewBox="0 0 350 179" role="img" aria-label="${state.period}天${kind==='cost'?'食材成本率':kind==='profit'?'利润率':'营收达成率'}趋势"><g>${[0,1,2,3,4].map(i=>`<line x1="32" x2="334" y1="${32+i*28}" y2="${32+i*28}" stroke="#e9edf4" stroke-dasharray="3 3"/><text x="25" y="${36+i*28}" text-anchor="end" class="chart-label">${Math.round(max-i*(max-min)/4)}%</text>`).join('')}</g><polyline points="32,${refY} 334,${refY}" fill="none" stroke="#b8c3d4" stroke-dasharray="4 4"/><polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#518df5" stroke-width="2" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="2.7" fill="#518df5" stroke="white"><title>${i+1}日：${vals[i].toFixed(1)}%</title></circle>`).join('')}${[0,1,2,3].map((v,i)=>`<text x="${32+i*100}" y="169" text-anchor="middle" class="chart-label">${state.period==='7'?['09/11','09/13','09/15','09/17'][i]:['08/19','08/29','09/08','09/17'][i]}</text>`).join('')}</svg><div class="legend"><span><i></i>${kind==='cost'?'食材成本率':kind==='profit'?'利润率':'营收达成率'}</span><span><i class="grey"></i>${kind==='cost'?'目标 35%':kind==='profit'?'参考 15%':'目标 100%'}</span></div>`}
function trends(kind='sales'){return `<div class="card card-pad"><div class="row"><div class="chart-title">${kind==='cost'?'成本率':kind==='profit'?'利润率':'营收达成率'}趋势</div><div><button class="link-btn" data-period="7" ${state.period==='7'?'style="font-weight:700"':''}>7天</button><button class="link-btn" data-period="30" ${state.period==='30'?'style="font-weight:700"':''}>30天</button></div></div>${chart(kind)}</div>`}
function ranks(mode='sales',limit=5){return stores.slice(1).sort((a,b)=>mode==='cost'?b.cost-a.cost:mode==='profit'?b.sales*b.profit-a.sales*a.profit:b.sales-a.sales).slice(0,limit).map((s,i)=>`<button class="rank" data-store="${s.id}"><div class="row"><span class="name"><span class="num">${i+1}</span>${s.name} ▸</span><span class="amount ${mode==='cost'&&s.cost>.35?'red':''}">${mode==='cost'?pct(s.cost):'¥ '+money(s.sales*factor()*(mode==='profit'?s.profit:1))}</span></div><div class="track"><div style="width:${mode==='cost'?s.cost*200:s.sales/46000*100}%;${mode==='cost'&&s.cost>.35?'background:var(--red)':''}"></div></div><div class="rank-footer"><span>${mode==='profit'?'利润率 '+pct(s.profit):'营业目标 ¥ '+money(s.target*factor())}</span><span class="${s.sales/s.target<.9?'red':''}">达成 ${pct(s.sales/s.target)}</span></div></button>`).join('')}
function home(){const s=current(),p=s.sales*s.profit;return hero()+`<div class="stamp"><span>2026/09/18 08:00 更新</span><span>模拟数据</span></div><div class="card opportunity"><h2>改善机会 <button class="link-btn" data-info="opportunity" aria-label="改善机会说明">ⓘ</button></h2>${metric('营收达成率',`目标 ${money(s.target)} 元，营收缺口 ${money(s.target-s.sales)} 元`,pct(s.sales/s.target),'revenue')}${metric('食材成本率',`目标 ≤35%，实际 ${pct(s.cost)}，${s.cost>.35?'超出':'低于'} ${Math.abs(s.cost*100-35).toFixed(1)} 个百分点`,pct(s.cost),'cost',s.cost>.35)}${metric('人工成本率',`目标 ≤22%，实际 ${pct(s.labor)}，${s.labor>.22?'超出':'低于'} ${Math.abs(s.labor*100-22).toFixed(1)} 个百分点`,pct(s.labor),'labor',s.labor>.22)}</div>${section('经营总览')}<div class="card grid">${kpi('净营业额',value(s.sales),unit(s.sales),'目标完成 '+pct(s.sales/s.target),'revenue',true)}${kpi('预估经营利润',value(p),unit(p),'利润率 '+pct(s.profit),'profit')}${kpi('有效订单',money(s.orders),'单','堂食 + 外卖','orders')}${kpi('单均消费',(s.sales/s.orders).toFixed(2),'元','净营业额 ÷ 有效订单','orders')}</div>${trends()}${section('门店经营排名','点击门店查看明细')}<div class="card">${ranks('sales',5)}</div>${section('资金概览','品牌汇总')}<div class="card grid">${kpi('可用资金','86.52','万','账面可用余额','cash')}${kpi('近 7 天应付','32.80','万','资金覆盖 2.64 倍','cash')}</div>${foot()}`}
function revenue(){const s=current();return hero('revenue')+`<div class="card card-pad"><div class="chart-title">营收达成概览</div><div class="row progress-label"><span>营收达成率</span><b class="red">${pct(s.sales/s.target)}</b></div><div class="big-track"><div style="width:${Math.min(100,s.sales/s.target*100)}%"></div></div><div class="explain">实际营收 ${money(s.sales)} 元 ｜ 目标营收 ${money(s.target)} 元</div></div>${trends()}${section('营业渠道构成')}<div class="card">${[['堂食',.58],['美团外卖',.28],['饿了么',.14]].map(([n,p])=>`<div class="rank"><div class="row"><span class="name">${n}</span><span class="amount">¥ ${money(s.sales*p)} · ${pct(p)}</span></div><div class="track"><div style="width:${p*100}%"></div></div></div>`).join('')}</div>${section('总营收差额拆解')}<div class="card card-pad"><div class="row"><span class="progress-label">较目标差额</span><b class="red">−¥ ${money(s.target-s.sales)}</b></div></div>${[['堂食订单量',.45],['堂食单均价',-.1],['外卖订单量',.5],['外卖单均价',.15]].map(([n,p])=>`<div class="card attribution ${p<0?'good':''}"><div class="attribution-top"><b>${n}</b><b>${p<0?'+':'−'}¥ ${money((s.target-s.sales)*Math.abs(p))}</b></div><div class="attribution-bottom"><div class="row explain"><span>差额贡献占比</span><span>${pct(p)}</span></div><div class="track"><div style="width:${Math.abs(p)*100}%"></div></div></div>`).join('')}<div class="explain" style="padding:0 14px">模拟拆解：正贡献表示扩大缺口，负贡献表示抵消缺口。</div>${section('门店营收排名')}<div class="card">${ranks()}</div>${foot()}`}
function profit(){const s=current();const rows=[['净营业额',s.sales],['食材成本',s.sales*s.cost],['人工成本',s.sales*s.labor],['租金及其他费用',s.sales*(1-s.cost-s.labor-s.profit)],['预估经营利润',s.sales*s.profit]];return hero('profit')+`<div class="notice">按食材、人工及费用分摊预估，非财务结账净利润。</div><div class="card grid">${kpi('预估经营利润',value(s.sales*s.profit),unit(s.sales*s.profit),'当前统计范围','profit')}${kpi('经营利润率',(s.profit*100).toFixed(1),'%','利润 ÷ 净营业额','profit')}</div>${section('利润构成')}<div class="card table-wrap"><table><thead><tr><th>项目</th><th>金额 / 元</th><th>占营收比</th></tr></thead><tbody>${rows.map(([n,v])=>`<tr><td>${n}</td><td>${money(v)}</td><td>${pct(v/s.sales)}</td></tr>`).join('')}</tbody></table></div>${trends('profit')}${section('门店利润排名')}<div class="card">${ranks('profit')}</div>${foot()}`}
function cost(labor=false){const s=current(),rate=labor?s.labor:s.cost,target=labor?.22:.35,route=labor?'labor':'cost';return hero(route)+`<div class="card card-pad"><div class="row"><span class="chart-title">${labor?'人工':'食材'}成本率</span><b class="${rate>target?'red':'green'}" style="font-size:24px">${pct(rate)}</b></div><div class="big-track"><div style="width:${rate*200}%;background:${rate>target?'var(--red)':'var(--green)'}"></div></div><div class="explain">目标 ≤${pct(target)} ｜ ${rate>target?'超出':'低于'} ${Math.abs(rate-target)*100<.01?'0.0':(Math.abs(rate-target)*100).toFixed(1)} 个百分点</div></div>${section('成本构成')}<div class="card table-wrap"><table><thead><tr><th>项目</th><th>金额 / 元</th><th>占成本比</th></tr></thead><tbody>${(labor?[['固定薪酬',.72],['计时与加班',.18],['社保及福利',.1]]:[['主料耗用',.61],['辅料与调味',.23],['包装耗用',.11],['报损',.05]]).map(([n,p])=>`<tr><td>${n}</td><td>${money(s.sales*rate*p)}</td><td>${pct(p)}</td></tr>`).join('')}</tbody></table></div>${labor?`<div class="card card-pad"><div class="chart-title">用工效率</div><div class="row minor"><span>总工时（模拟）</span><b>${money(s.orders*.12)} 小时</b></div><div class="row minor"><span>每工时营业额</span><b>¥ ${(s.sales/(s.orders*.12)).toFixed(1)}</b></div></div>`:trends('cost')}${section('门店成本对比')}<div class="card">${labor?stores.slice(1).map(st=>`<button class="rank" data-store="${st.id}"><div class="row"><span class="name">${st.name} ▸</span><b class="${st.labor>.22?'red':'green'}">${pct(st.labor)}</b></div></button>`).join(''):ranks('cost')}</div>${foot()}`}
function cash(){return hero('cash')+`<div class="notice">资金为品牌当前时点余额，不随经营日期和门店筛选变化。</div><div class="card grid">${kpi('可用资金','86.52','万','截至 09/18 08:00','cash')}${kpi('平台待结算','12.64','万','预计未来 3 天到账','cash')}</div>${section('近 7 天付款计划')}<div class="card table-wrap"><table><thead><tr><th>款项</th><th>到期日</th><th>金额 / 元</th></tr></thead><tbody><tr><td>供应商货款</td><td>09/20</td><td>128,000</td></tr><tr><td>员工薪资</td><td>09/22</td><td>146,000</td></tr><tr><td>门店租金</td><td>09/24</td><td>54,000</td></tr><tr><td>合计</td><td>近7天</td><td>328,000</td></tr></tbody></table></div><div class="card card-pad"><div class="row minor"><span>付款后可用资金（不含待结算）</span><b class="green">¥ 537,200</b></div></div>${foot()}`}
function storePage(){const s=current();return hero('store')+`<div class="card grid">${kpi('净营业额',value(s.sales),unit(s.sales),'目标达成 '+pct(s.sales/s.target),'revenue',true)}${kpi('预估经营利润',value(s.sales*s.profit),unit(s.sales*s.profit),'利润率 '+pct(s.profit),'profit')}</div><div class="card opportunity"><h2>门店改善机会</h2>${metric('营收达成率','距目标差额 ¥ '+money(s.target-s.sales),pct(s.sales/s.target),'revenue')}${metric('食材成本率','目标 ≤35%',pct(s.cost),'cost',s.cost>.35)}${metric('人工成本率','目标 ≤22%',pct(s.labor),'labor',s.labor>.22)}</div>${trends()}${foot()}`}
function orders(){const s=current();return hero('orders')+`<div class="card grid">${kpi('有效订单',money(s.orders),'单','已完成且未全额退款','orders')}${kpi('单均消费',(s.sales/s.orders).toFixed(2),'元','以订单为单位，非人均','orders')}</div>${section('渠道订单明细')}<div class="card table-wrap"><table><thead><tr><th>渠道</th><th>订单数</th><th>营业额 / 元</th><th>单均 / 元</th></tr></thead><tbody>${[['堂食',.52,.58],['美团外卖',.32,.28],['饿了么',.16,.14]].map(([n,q,p])=>`<tr><td>${n}</td><td>${money(s.orders*q)}</td><td>${money(s.sales*p)}</td><td>${(s.sales*p/Math.round(s.orders*q)).toFixed(2)}</td></tr>`).join('')}</tbody></table></div>${foot()}`}
function render(restore=false){let route=currentRoute();if(!titles[route])route='home';document.title=titles[route]+' · 演示';document.getElementById('app').innerHTML=`<header>${route==='home'?'':`<button id="back" aria-label="返回上一页">‹</button>`}<h1>${titles[route]}</h1><span class="demo">DEMO</span></header>`+({home,revenue,profit,cost:()=>cost(false),labor:()=>cost(true),cash,store:storePage,orders,stores:()=>hero('stores')+`<div class="card">${ranks()}</div>`}[route]())+`<dialog id="info"><h3>改善机会</h3><p>按当前门店与日期显示营收缺口、食材及人工成本差异。红色表示未达目标，绿色表示达标。所有数值均为演示数据。</p><button id="close-info">知道了</button></dialog>`;
document.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>go(el.dataset.go));document.querySelectorAll('[data-store]').forEach(el=>el.onclick=()=>go('store',el.dataset.store));document.querySelectorAll('[data-period]').forEach(el=>el.onclick=()=>{state.period=el.dataset.period;render()});document.querySelectorAll('[data-info]').forEach(el=>el.onclick=()=>document.getElementById('info').showModal());document.getElementById('close-info').onclick=()=>document.getElementById('info').close();const b=document.getElementById('back');if(b)b.onclick=()=>{if(history.state?.depth>0)history.back();else go('home')};document.getElementById('store-filter').onchange=e=>{state.store=e.target.value;persist();render()};document.getElementById('day-filter').onchange=e=>{state.day=e.target.value;persist();render()};if(restore)window.scrollTo(0,savedScroll[route]||0)}
history.scrollRestoration='manual';window.addEventListener('popstate',()=>{if(history.state?.filters)Object.assign(state,history.state.filters);render();window.scrollTo(0,history.state?.scroll||0)});if(history.state?.filters)Object.assign(state,history.state.filters);persist();render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_dashboard_filters',description:'设置演示看板门店与日期范围，与页面筛选器同步。',inputSchema:{type:'object',properties:{store:{type:'string',enum:stores.map(s=>s.id)},day:{type:'string',enum:['yesterday','week','month']}},required:['store','day'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!stores.some(s=>s.id===input.store)||!['yesterday','week','month'].includes(input.day))throw Error('筛选值无效');Object.assign(state,{store:input.store,day:input.day});persist();render();return {store:current().name,day:state.day,simulated:true};}})).catch(()=>{});}catch{}}
